function ProjectExperienceDecal(){
 const texture=useTexture(tex('project-experience-sign.webp'));
 texture.colorSpace=SRGBColorSpace;
 // Anchor the visible artwork, excluding the PNG's transparent margins, to the rear wall.
 const width=.5368,height=width*.75;
 const left=bayLeft(1)+.08,top=OPENING_TOP-.035;
 const x=left+width*(.5-.077),y=top-height*(.5-.132);
 // Cavity_Back's front face is CAVITY_BACK_Z + .008 + .012 / 2.
 return <mesh name="ProjectExperience_BackWallDecal" position={[x,y,CAVITY_BACK_Z+.016]} raycast={()=>null}>
  <planeGeometry args={[width,height]}/>
  <meshBasicMaterial map={texture} transparent alphaTest={.02} toneMapped={false} depthWrite={false} polygonOffset polygonOffsetFactor={-1} polygonOffsetUnits={-1}/>
 </mesh>
}
