function useTagTextTexture(text:string,dark:boolean){const texture=useMemo(()=>{const canvas=document.createElement('canvas');canvas.width=1024;canvas.height=320;const ctx=canvas.getContext('2d')!;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle=dark?'#f7f4ef':'#17171b';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=text.includes('Anko')?'700 112px "Microsoft YaHei",Arial,sans-serif':'750 132px "Microsoft YaHei",sans-serif';ctx.fillText(text,canvas.width/2,canvas.height/2);const output=new CanvasTexture(canvas);output.colorSpace=SRGBColorSpace;output.anisotropy=16;return output},[text,dark]);useEffect(()=>()=>texture.dispose(),[texture]);return texture}

